local ENV=_ENV or (getfenv and getfenv())
local unpackValues=table.unpack or unpack
local function packValues(...) return {n=select('#',...),...} end
local run
run=function(id,u,...)
  local p=P[id]
  local r={}
  local params,k,code=p[1],p[2],p[3]
  for n=1,params do r[n-1]=select(n,...) end
  local pc=1
  while true do
    local base=pc
    local o=code[base]
    pc=pc+code[base+1]
    if o==1 then r[code[base+2]]=k[code[base+3]]
    elseif o==41 then
      if not r[code[base+2]] then pc=code[base+3] else pc=code[base+4] end
    elseif o==42 then
      r[code[base+2]]=k[code[base+3]]
      r[code[base+4]]=r[code[base+5]]+r[code[base+6]]
    elseif o==43 then
      r[code[base+2]]=k[code[base+3]]
      r[code[base+4]]=r[code[base+5]][r[code[base+6]]]
    elseif o==44 then
      r[code[base+2]]=k[code[base+3]]
      r[code[base+4]][r[code[base+5]]]=r[code[base+6]]
    elseif o==2 then r[code[base+2]]=r[code[base+3]]
    elseif o==3 then r[code[base+2]]=ENV[k[code[base+3]]]
    elseif o==4 then ENV[k[code[base+2]]]=r[code[base+3]]
    elseif o==5 then r[code[base+2]]={}
    elseif o==6 then r[code[base+2]]=r[code[base+3]][r[code[base+4]]]
    elseif o==7 then r[code[base+2]][r[code[base+3]]]=r[code[base+4]]
    elseif o==8 then r[code[base+2]]=-r[code[base+3]]
    elseif o==9 then r[code[base+2]]=not r[code[base+3]]
    elseif o==10 then r[code[base+2]]=#r[code[base+3]]
    elseif o==11 then r[code[base+2]]=r[code[base+3]]+r[code[base+4]]
    elseif o==12 then r[code[base+2]]=r[code[base+3]]-r[code[base+4]]
    elseif o==13 then r[code[base+2]]=r[code[base+3]]*r[code[base+4]]
    elseif o==14 then r[code[base+2]]=r[code[base+3]]/r[code[base+4]]
    elseif o==15 then r[code[base+2]]=r[code[base+3]]//r[code[base+4]]
    elseif o==16 then r[code[base+2]]=r[code[base+3]]%r[code[base+4]]
    elseif o==17 then r[code[base+2]]=r[code[base+3]]^r[code[base+4]]
    elseif o==18 then r[code[base+2]]=r[code[base+3]]..r[code[base+4]]
    elseif o==19 then r[code[base+2]]=r[code[base+3]]==r[code[base+4]]
    elseif o==20 then r[code[base+2]]=r[code[base+3]]~=r[code[base+4]]
    elseif o==21 then r[code[base+2]]=r[code[base+3]]<r[code[base+4]]
    elseif o==22 then r[code[base+2]]=r[code[base+3]]<=r[code[base+4]]
    elseif o==23 then r[code[base+2]]=r[code[base+3]]>r[code[base+4]]
    elseif o==24 then r[code[base+2]]=r[code[base+3]]>=r[code[base+4]]
    elseif o==25 and code[base+5]==0 and code[base+4]<=4 then
      local f=r[code[base+3]]
      local count=code[base+4]
      if count==0 then r[code[base+2]]=f()
      elseif count==1 then r[code[base+2]]=f(r[code[base+6]])
      elseif count==2 then r[code[base+2]]=f(r[code[base+6]],r[code[base+7]])
      elseif count==3 then r[code[base+2]]=f(r[code[base+6]],r[code[base+7]],r[code[base+8]])
      else r[code[base+2]]=f(r[code[base+6]],r[code[base+7]],r[code[base+8]],r[code[base+9]]) end
    elseif o==25 or o==37 then
      local a={}
      local count=code[base+4]
      for n=1,count do a[n]=r[code[base+5+n]] end
      local spread=code[base+5]
      if spread~=0 then
        local s=r[spread-1]
        for n=1,s.n do count=count+1;a[count]=s[n] end
      end
      if o==25 then r[code[base+2]]=r[code[base+3]](unpackValues(a,1,count))
      else r[code[base+2]]=packValues(r[code[base+3]](unpackValues(a,1,count))) end
    elseif o==26 then
      local target=code[base+3]
      local captures={}
      for n=1,code[base+4] do captures[n]=r[code[base+4+n]] end
      r[code[base+2]]=function(...) return run(target,captures,...) end
    elseif o==27 then pc=code[base+2]
    elseif o==28 then if not r[code[base+2]] then pc=code[base+3] end
    elseif o==29 then if code[base+2]==0 then return else return r[code[base+3]] end
    elseif o==30 then r[code[base+2]]={r[code[base+3]]}
    elseif o==31 then r[code[base+2]]=r[code[base+3]][1]
    elseif o==32 then r[code[base+2]][1]=r[code[base+3]]
    elseif o==33 then r[code[base+2]]=u[code[base+3]]
    elseif o==34 then
      local values={n=code[base+3]}
      for n=1,code[base+3] do values[n]=r[code[base+4+n]] end
      local spread=code[base+4]
      if spread~=0 then
        local s=r[spread-1]
        for n=1,s.n do values.n=values.n+1;values[values.n]=s[n] end
      end
      r[code[base+2]]=values
    elseif o==35 then r[code[base+2]]=r[code[base+3]][code[base+4]]
    elseif o==36 then
      r[code[base+2]]=packValues(select(params+1,...))
    elseif o==38 then
      local values=r[code[base+4]]
      for n=1,values.n do r[code[base+2]][code[base+3]+n-1]=values[n] end
    elseif o==39 then
      local index,limit,step=r[code[base+3]],r[code[base+4]],r[code[base+5]]
      if step>=0 then r[code[base+2]]=index<=limit else r[code[base+2]]=index>=limit end
    elseif o==40 then
      local values=r[code[base+2]]
      return unpackValues(values,1,values.n)
    else error("invalid Ravel opcode") end
  end
end

return run(0,{})
